exercises.solution:
use serde::{Deserialize, Serialize};

#[derive(Clone, Serialize, Deserialize)]
struct Product {
    id: i32,
    name: String,
    price: f64,
}

fn fmt_product(p: &Product) -> String {
    format!("{{{} {} {:.2}}}", p.id, p.name, p.price)
}

fn main() {
    let original = Product {
        id: 1,
        name: "Laptop".into(),
        price: 999.99,
    };
    let data = serde_json::to_string(&original).unwrap();
    let recovered: Product = serde_json::from_str(&data).unwrap();
    println!("Original: {}", fmt_product(&original));
    println!("Recovered: {}", fmt_product(&recovered));
}

